<script setup>
import { Head, router } from '@inertiajs/vue3'; import { ref } from 'vue'; import AppLayout from '../Layouts/AppLayout.vue';
const props=defineProps({records:Object}); const form=ref({status:'Activo'}); const member=ref({}); function save(){router.post('/consorcios',form.value)} function add(id){router.post(`/consorcios/${id}/miembros`,member.value)} function updateMember(c,m){router.put(`/consorcios/${c}/miembros/${m.id}`,m)} function remove(id){if(confirm('¿Eliminar consorcio?'))router.delete(`/consorcios/${id}`)} function removeMember(c,id){router.delete(`/consorcios/${c}/miembros/${id}`)}
</script>
<template><Head title="Consorcios"/><AppLayout><main class="module-page"><div class="module-header"><h2>Consorcios</h2></div><form class="module-form" @submit.prevent="save"><input v-model="form.name" required placeholder="Nombre"><input v-model="form.tender_id" placeholder="ID licitación"><input v-model="form.institution_id" placeholder="ID institución"><input v-model="form.leader_company_id" placeholder="ID empresa líder"><input v-model="form.amount" type="number" min="0" placeholder="Monto"><input v-model="form.formed_at" type="date"><input v-model="form.status" required placeholder="Estado"><textarea v-model="form.notes" placeholder="Notas"/><button class="module-primary">Crear consorcio</button></form><section v-for="row in records.data" :key="row.id" class="module-toolbar"><b>{{row.name}}</b><span>{{row.status}} · L {{row.amount}}</span><button class="row-action delete" @click="remove(row.id)">Eliminar</button><form v-for="m in row.members" :key="m.id" @submit.prevent="updateMember(row.id,m)"><input v-model="m.name" required><input v-model="m.participation_percentage" required type="number" min="0.01" max="100"><input v-model="m.role" placeholder="Rol"><input v-model="m.tax_id" placeholder="RTN"><input v-model="m.email" type="email" placeholder="Correo"><input v-model="m.phone" placeholder="Teléfono"><button class="row-action">Actualizar miembro</button><button type="button" class="row-action delete" @click="removeMember(row.id,m.id)">Quitar</button></form><form @submit.prevent="add(row.id)"><input v-model="member.name" required placeholder="Miembro"><input v-model="member.participation_percentage" required type="number" min="0.01" max="100" placeholder="Participación %"><input v-model="member.role" placeholder="Rol"><input v-model="member.tax_id" placeholder="RTN"><input v-model="member.email" type="email" placeholder="Correo"><input v-model="member.phone" placeholder="Teléfono"><button class="row-action">Agregar miembro</button></form></section></main></AppLayout></template>
